{
  "type": "client-request",
  "rpcId": "{{$guid}}",
  "method": "session.prompt",
  "payload": {
    "sessionId": "{{sessionId}}",
    "mode": "queue",
    "content": [
      {
        "type": "text",
        "text": "Hello! Please list the files in this project."
      }
    ],
    "clientTimeZone": "Asia/Ho_Chi_Minh"
  }
}

response.body:
{
  "type": "server-response",
  "rpcId": "{{$guid}}",
  "result": {
    "ok": true,
    "value": {
      "presets": [
        {
          "id": "base",
          "trust": "system",
          "isDefault": true,
          "name": "Base"
        },
        {
          "id": "my-preset",
          "trust": "user",
          "isDefault": false,
          "name": "My Preset",
          "workspacePath": "/Users/dev01/workspace/my-preset"
        }
      ],
      "authorable": true,
      "hasDocument": true
    }
  }
}

